import json

with open('baseline-packages.json') as f:
    baseline = json.load(f)
with open('after-cpm-packages.json') as f:
    after = json.load(f)

def extract_packages(data):
    result = {}
    for project in data.get('projects', []):
        proj_name = project['path'].split('/')[-1]
        pkgs = {}
        for fw in project.get('frameworks', []):
            fw_name = fw['framework']
            for pkg in fw.get('topLevelPackages', []):
                key = (pkg['id'], fw_name)
                pkgs[key] = pkg['resolvedVersion']
        result[proj_name] = pkgs
    return result

b = extract_packages(baseline)
a = extract_packages(after)

changes = []
unchanged = []

all_projects = set(list(b.keys()) + list(a.keys()))
for proj in sorted(all_projects):
    bp = b.get(proj, {})
    ap = a.get(proj, {})
    all_keys = set(list(bp.keys()) + list(ap.keys()))
    for key in sorted(all_keys):
        pkg_id, fw = key
        bv = bp.get(key)
        av = ap.get(key)
        if bv != av:
            changes.append((proj, pkg_id, fw, bv or '(none)', av or '(none)'))
        else:
            unchanged.append((proj, pkg_id, fw, bv))

print('=== CHANGES ===')
if changes:
    for c in changes:
        print(f'  {c[0]} | {c[1]} ({c[2]}) | {c[3]} -> {c[4]}')
else:
    print('  None')

print(f'\n=== UNCHANGED: {len(unchanged)} packages ===')
for u in unchanged[:5]:
    print(f'  {u[0]} | {u[1]} ({u[2]}) | {u[3]}')
if len(unchanged) > 5:
    print(f'  ... and {len(unchanged)-5} more')
"

